Interp function: find segment, use smoothstep t for smooth C1 interpolation.

```js
function loftSample(y){
  const T = TRUNK;
  if (y >= T[0][0]) return {a:T[0][1], b:T[0][2], cz:T[0][3], n:T[0][4]};
  const last = T[T.length-1];
  if (y <= last[0]) return {a:last[1], b:last[2], cz:last[3], n:last[4]};
  for (let i=0;i<T.length-1;i++){
    if (y <= T[i][0] && y >= T[i+1][0]){
      const t = (T[i][0]-y)/(T[i][0]-T[i+1][0]);
