function loftAt(tab, y){
  // tab: array of [y, cx, cz, a, b, n], y descending
  if (y > tab[0][0] || y < tab[tab.length-1][0]) return null;
  for (let i=0;i<tab.length-1;i++){
    const y0=tab[i][0], y1=tab[i+1][0];
    if (y<=y0 && y>=y1){
      const t=(y0-y)/(y0-y1), s=t*t*(3-2*t);
      return [ lerp(tab[i][1],tab[i+1][1],s), lerp(tab[i][2],tab[i+1][2],s),
               lerp(tab[i][3],tab[i+1][3],s), lerp(tab[i][4],tab[i+1][4],s),
               lerp(tab[i][5],tab[i+1][5],s) ];
    }
  }
  return null;
}
