```glsl
// ---- shared noise ----
float hash31(vec3 p){
  p = fract(p*0.1031);
  p += dot(p, p.yzx + 33.33);
  return fract((p.x + p.y) * p.z);
}
float vnoise(vec3 x){
  vec3 i = floor(x), f = fract(x);
  vec3 u = f*f*(3.0-2.0*f);
  float a = mix(mix(hash31(i), hash31(i+vec3(1,0,0)), u.x),
                mix(hash31(i+vec3(0,1,0)), hash31(i+vec3(1,1,0)), u.x), u.y);
  float b = mix(mix(hash31(i+vec3(0,0,1)), hash31(i+vec3(1,0,1)), u.x),
                mix(hash31(i+vec3(0,1,1)), hash31(i+vec3(1,1,1)), u.x), u.y);
  return mix(a, b, u.z);
}
float fbm3(vec3 p){
  float s = 0.0, a = 0.5;
  for (int i=0;i<3;i++){ s += a*vnoise(p); p = p*2.07 + vec3(11.3,7.7,3.1); a *= 0.5; }
  return s;
}
```
