For the vertex displacement GLSL:

```glsl
#define NPOKES 12
uniform vec4 uPokeA[NPOKES];
uniform vec4 uPokeB[NPOKES];
uniform float uTissueBulge;

vec3 tissueDisp(vec3 p){
  vec3 d = vec3(0.0);
  for (int i = 0; i < NPOKES; i++){
    float amp = uPokeA[i].w;
    if (amp == 0.0) continue;
    vec3 c = uPokeA[i].xyz;
    vec3 dir = uPokeB[i].xyz;
    float R = uPokeB[i].w;
    vec3 rel = p - c;
    float r = length(rel) + 1e-6;
    float t = clamp(1.0 - r / R, 0.0, 1.0);
    float g = t*t*(3.0 - 2.0*t);
    d -= dir * (amp * g);
    vec3 rad = rel - dir * dot(rel, dir);
    float rl = length(rad);
    float b = sin(t * 3.14159265);
    d += (rad / rl) * (amp * uTissueBulge * b);
  }
  return d;
}
vec3 tissueNormal(vec3 p, vec3 n){
  float e = 0.012;
  vec3 dx = tissueDisp(p + vec3(e,0.0,0.0)) - tissueDisp(p - vec3(e,0.0,0.0));
  vec3 dy = tissueDisp(p + vec3(0.0,e,0.0)) - tissueDisp(p - vec3(0.0,e,0.0));
  vec3 dz = tissueDisp(p + vec3(0.0,0.0,e)) - tissueDisp(p - vec3(0.0,0.0,e));
  mat3 J = mat3(dx, dy, dz) / (2.0*e);
  vec3 t1 = abs(n.y) < 0.9 ? normalize(cross(vec3(0.0,1.0,0.0), n)) : normalize(cross(vec3(1.0,0.0,0.0), n));
  vec3 t2 = cross(n, t1);
  vec3 T1 = t1 + J * t1;
  vec3 T2 = t2 + J * t2;
  vec3 nd = cross(T1, T2);
  float L = length(nd);
  if (L < 1e-8) return n;
  nd = nd / L;
  return dot(nd, n) < 0.0 ? -nd : nd;
}
```
Note: `mat3(dx,dy,dz)` in GLSL takes columns. J's column i = (D(p+e_i)-D(p-e_i))/(2e) = ∂D/∂p_i. So J*v = Σ v_i ∂D/∂p_i ✓ correct Jacobian action.

GLSL ternary with vec3 is fine.

