function march(vals, NX, NY, NZ) {
  const SX = NX + 1, SY = NY + 1;
  const SZ = NZ + 1;
  const plane = SY * SX;
  const pos = [], nor = [], idx = [];
  const cache = new Map();
  const vert = new Int32Array(12);
  const n = vals.length;

  for (let k = 0; k < NZ; k++) {
    for (let j = 0; j < NY; j++) {
      const q0 = (k * SY + j) * SX;
      const q1 = q0 + plane;
      for (let i = 0; i < NX; i++) {
        const q = q0 + i;
        const v0 = vals[q], v1 = vals[q + 1], v2 = vals[q + 1 + SX], v3 = vals[q + SX];
        const v4 = vals[q1], v5 = vals[q1 + 1], v6 = vals[q1 + 1 + SX], v7 = vals[q1 + SX];
        let mask = 0;
        if (v0 > 0) mask |= 1;
        if (v1 > 0) mask |= 2;
        if (v2 > 0) mask |= 4;
        if (v3 > 0) mask |= 8;
        if (v4 > 0) mask |= 16;
        if (v5 > 0) mask |= 32;
        if (v6 > 0) mask |= 64;
        if (v7 > 0) mask |= 128;
        const et = edgeTable[mask];
        if (et === 0) continue;

        for (let e = 0; e < 12; e++) {
          if ((et & (1 << e)) === 0) { vert[e] = -1; continue; }
          const E = EDGE[e];
          const bi = i + E[0], bj = j + E[1], bk = k + E[2];
          const axis = E[3];
          const key = ((bk * SY + bj) * NX + bi) * 3 + axis;
          let vi = cache.get(key);
          if (vi === undefined) {
            const o0 = (bk * SY + bj) * SX + bi;
            const step = axis === 0 ? 1 : axis === 1 ? SX : plane;
            const a = vals[o0], b = vals[o0 + step];
            const mu = -a / (b - a || 1e-12);
            // gradient of the implicit field, blended across the edge
            let gx = 0, gy = 0, gz = 0;
            for (let d = 0; d < 3; d++) {
              const s = d === 0 ? 1 : d === 1 ? SX : plane;
              const pa = vals[clampIdx(o0 + s, n)] - vals[clampIdx(o0 - s, n)];
              const pb = vals[clampIdx(o0 + step + s, n)] - vals[clampIdx(o0 + step - s, n)];
              const g = pa + (pb - pa) * mu;
              if (d === 0) gx = g; else if (d === 1) gy = g; else gz = g;
            }
            const L = Math.sqrt(gx * gx + gy * gy + gz * gz) || 1e-9;
            const px = bi + (axis === 0 ? mu : 0);
            const py = bj + (axis === 1 ? mu : 0);
            const pz = bk + (axis === 2 ? mu : 0);
            vi = pos.length / 3;
            pos.push(px, py, pz);
            nor.push(gx / L, gy / L, gz / L);
            cache.set(key, vi);
          }
          vert[e] = vi;
        }

        const trow = mask * 16;
        for (let t = 0; t < 16; t += 3) {
          const ta = triTable[trow + t];
          if (ta < 0) break;
          idx.push(vert[ta], vert[triTable[trow + t + 1]], vert[triTable[trow + t + 2]]);
        }
      }
    }
  }
  return { pos, nor, idx };
}

