function march(vals, NX, NY, NZ) {
  const SX = NX + 1, SY = NY + 1;
  const SZ = NZ + 1;
  const plane = SY * SX;
  const pos = [], nor = [], idx = [];
  const cache = new Map();
  const vert = new Int32Array(12);
  let badMu = 0;
  const n = vals.length;

  for (let k = 0; k < NZ; k++) {
    for (let j = 0; j < NY; j++) {
      const q0 = (k * SY + j) * SX;
      const q1 = q0 + plane;
      for (let i = 0; i < NX; i++) {
        const q = q0 + i;
        const v0 = vals[q], v1 = vals[q + 1], v2 = vals[q + 1 + SX], v3 = vals[q + SX];
        const v4 = vals[q1], v5 = vals[q1 + 1], v6 = vals[q1 + 1 + SX], v7 = vals[q1 + SX];
        let mask = 0;
        if (v0 > 0) mask |= 1;
        if (v1 > 0) mask |= 2;
        if (v2 > 0) mask |= 4;
        if (v3 > 0) mask |= 8;
        if (v4 > 0) mask |= 16;
        if (v5 > 0) mask |= 32;
        if (v6 > 0) mask |= 64;
        if (v7 > 0) mask |= 128;
        const et = edgeTable[mask];
        if (et === 0) continue;

        for (let e = 0; e < 12; e++) {
          if ((et & (1 << e)) === 0) { vert[e] = -1; continue; }
          const E = EDGE[e];
          const bi = i + E[0], bj = j + E[1], bk = k + E[2];
          const axis = E[3];
          const key = ((bk * SY + bj) * NX + bi) * 3 + axis;
          let vi = cache.get(key);
          if (vi === undefined) {
            const o0 = (bk * SY + bj) * SX + bi;
            const step = axis === 0 ? 1 : axis === 1 ? SX : plane;
