edits.oldText:
/* >0 where the swimwear leg opening removes fabric */
function legCut(ax, y, z) {
  if (ax <= SW.gusset) return -BIG;
  const py = SW.c0 + SW.cz * z + SW.cx * (ax - SW.gusset);
  return smin(ax - SW.gusset, py - y, 0.020);
}

function maskValue(x, y, z, ax) {
  const cut = legCut(ax, y, z);
  let m = smax(y - SW.bandTop, SW.bandBot - y, SW.kBand);
  m = smax(m, cut, SW.kCut);
  return m;
}

