/* =====================================================================
   6b.  Swimwear: offset shell built directly from the body surface
   ===================================================================== */

function buildFabric(bodyGeo) {
  const P = bodyGeo.getAttribute('position');
  const N = bodyGeo.getAttribute('normal');
  const CO = bodyGeo.getAttribute('color');
  const I = bodyGeo.getIndex();
  const T = SW.thickness;

  const cov = new Float32Array(P.count);
  for (let i = 0; i < P.count; i++) {
    const x = P.getX(i), y = P.getY(i), z = P.getZ(i);
    cov[i] = -maskValue(x, y, z, Math.abs(x));
  }

  const op = [], on = [], oc = [], oi = [];
  function addV(x, y, z, nx, ny, nz, r, g, b) {
    op.push(x, y, z); on.push(nx, ny, nz); oc.push(r, g, b);
    return op.length / 3 - 1;
  }
  const offIdx = new Int32Array(P.count);
  for (let i = 0; i < P.count; i++) {
    const nx = N.getX(i), ny = N.getY(i), nz = N.getZ(i);
    offIdx[i] = addV(P.getX(i) + nx * T, P.getY(i) + ny * T, P.getZ(i) + nz * T, nx, ny, nz,
                    CO.getX(i), CO.getY(i), CO.getZ(i));
  }
  function lerpV(i, j, t) {
    const x = P.getX(i) + (P.getX(j) - P.getX(i)) * t;
    const y = P.getY(i) + (P.getY(j) - P.getY(i)) * t;
    const z = P.getZ(i) + (P.getZ(j) - P.getZ(i)) * t;
    let nx = N.getX(i) + (N.getX(j) - N.getX(i)) * t;
    let ny = N.getY(i) + (N.getY(j) - N.getY(i)) * t;
    let nz = N.getZ(i) + (N.getZ(j) - N.getZ(i)) * t;
    const L = Math.sqrt(nx * nx + ny * ny + nz * nz) || 1;
    return { x, y, z, nx: nx / L, ny: ny / L, nz: nz / L,
             r: CO.getX(i) + (CO.getX(j) - CO.getX(i)) * t,
             g: CO.getY(i) + (CO.getY(j) - CO.getY(i)) * t,
             b: CO.getZ(i) + (CO.getZ(j) - CO.getZ(i)) * t };
  }
  function gradMask(x, y, z) {
    const e = 0.004;
    const m = (a, b, c) => maskValue(a, b, c, Math.abs(a));
    return [
      (m(x + e, y, z) - m(x - e, y, z)) / (2 * e),
      (m(x, y + e, z) - m(x, y - e, z)) / (2 * e),
      (m(x, y, z + e) - m(x, y, z - e)) / (2 * e)
    ];
  }

  const HEM = 1.0;
  for (let f = 0; f < I.count; f += 3) {
    const a = I.getX(f), b = I.getX(f + 1), c = I.getX(f + 2);
    const sa = cov[a] > 0, sb = cov[b] > 0, sc = cov[c] > 0;
    if (!sa && !sb && !sc) continue;
    if (sa && sb && sc) { oi.push(offIdx[a], offIdx[b], offIdx[c]); continue; }

    const tri = [a, b, c];
    const out = [];
    for (let i = 0; i < 3; i++) {
      const cur = tri[i], nxt = tri[(i + 1) % 3];
      const ci = cov[cur], cn = cov[nxt];
      const cin = ci > 0, nin = cn > 0;
      if (cin) out.push({ k: 'v', idx: cur });
      if (cin !== nin) out.push({ k: 'p', i: cur, j: nxt, t: ci / (ci - cn) });
    }
    if (out.length < 3) continue;

    const ids = out.map(o => {
      if (o.k === 'v') return offIdx[o.idx];
      const v = lerpV(o.i, o.j, o.t);
