/* how deep the groove is cut into the back surface */
const CLEFT_DEPTH = [
  [1.128, 0.000], [1.100, 0.007], [1.060, 0.014], [1.020, 0.019],
  [0.980, 0.023], [0.940, 0.027], [0.900, 0.030], [0.860, 0.031],
  [0.820, 0.030], [0.790, 0.027], [0.768, 0.021], [0.750, 0.012],
  [0.735, 0.003]
];
/* half-width of the groove (x) */
const CLEFT_WID = [
  [1.128, 0.009], [1.100, 0.014], [1.060, 0.019], [1.020, 0.023],
  [0.980, 0.026], [0.940, 0.028], [0.900, 0.030], [0.860, 0.030],
  [0.820, 0.029], [0.790, 0.027], [0.768, 0.024], [0.750, 0.019],
  [0.735, 0.013]
];
/* half extent of the cutter along z (controls the roundness of the groove) */
const CLEFT_RAD = [
  [1.128, 0.022], [1.060, 0.028], [1.000, 0.032], [0.940, 0.035],
  [0.880, 0.037], [0.820, 0.037], [0.780, 0.034], [0.750, 0.030],
  [0.735, 0.026]
];

function makeRowBase(y) {
  return { T: loftAt(T_TRUNK, y), C: loftAt(T_CHEEK, y), H: loftAt(T_THIGH, y) };
}

function bodyBaseValue(x, z, ax, R) {
  let v = BIG;
  const T = R.T;
  if (T) v = sf2(x - T[0], z - T[1], T[2], T[3], T[4]);
  const C = R.C;
  if (C) v = smin(v, sf2(ax - C[0], z - C[1], C[2], C[3], C[4]), BLEND.cheek);
  const H = R.H;
  if (H) v = smin(v, sf2(ax - H[0], z - H[1], H[2], H[3], H[4]), BLEND.thigh);
  v = smax(v, yCur - CUT.top, CUT.k);
  v = smax(v, CUT.bottom - yCur, CUT.k);
  return v;
}

/* back surface (z) on the midline, blend-accurate, found by bisection */
function backZMid(y) {
  const R = makeRowBase(y);
  const f = (z) => { yCur = y; return bodyBaseValue(0, z, 0, R); };
  const step = 0.003;
  let prev = f(-0.32);
  for (let z = -0.32 + step; z < 0.0; z += step) {
    const v = f(z);
    if (prev > 0 && v <= 0) {
      let a = z - step, b = z;
      for (let it = 0; it < 26; it++) {
        const m = (a + b) * 0.5;
        if (f(m) > 0) a = m; else b = m;
      }
      return b;
    }
    prev = v;
  }
  return -0.15;
}

/* back surface height (z) on the midline, from trunk + cheeks */
function backZMidApprox(y) {
  let s = -BIG;
  const T = loftAt(T_TRUNK, y);
  if (T) s = Math.max(s, T[1] - T[3]);
  const C = loftAt(T_CHEEK, y);
  if (C) {
    const k = C[0] / C[2];
    if (Math.abs(k) < 1) s = Math.max(s, C[1] - C[3] * Math.sqrt(1 - k * k));
  }
  return s;
}

/* =====================================================================
   3b.  Field evaluation
   ===================================================================== */

/* Pre-computed per grid row so the inner loops are cheap. */
function makeRow(y) {
  const R = makeRowBase(y);
  let G = null;
  const dep = profAt(CLEFT_DEPTH, y);
  if (dep > 0.0008) {
    const r = profAt(CLEFT_RAD, y);
    const w = profAt(CLEFT_WID, y);
    const bz = backZMid(y);
    G = { cz: bz + dep - r, w: w, r: r };
  }
  return { T: R.T, C: R.C, H: R.H, G };
}

function bodyValue(x, z, ax, R) {
  let v = bodyBaseValue(x, z, ax, R);
  const G = R.G;
  if (G && !NO_CLEFT) v = smax(v, -sf2(x, z - G.cz, G.w, G.r, 2.0), BLEND.cleft);
  return v;
}

