mat.onBeforeCompile = (shader) => {
  Object.assign(shader.uniforms, skinUniforms);
  injectTissue(shader, 'vSkinPos');
  shader.fragmentShader = `varying vec3 vSkinPos;
    uniform float uRough, uPoreR, uMidR, uBump, uColorVar;
    uniform vec3 uSSSColor; uniform float uSSS; uniform vec3 uSSSDir;
    ${GLSL_NOISE}
    const float PORE_SCALE = 230.0;
    const float PORE_E = 1.0 / PORE_SCALE;
  ` + shader.fragmentShader
    .replace('#include <color_fragment>', `#include <color_fragment>
      // one noise evaluation pass, reused by colour / roughness / bump
      float skinPore = fbm2(vSkinPos * PORE_SCALE);
      vec3  poreOff = vec3(
        fbm2((vSkinPos + vec3(PORE_E, 0.0, 0.0)) * PORE_SCALE),
        fbm2((vSkinPos + vec3(0.0, PORE_E, 0.0)) * PORE_SCALE),
        fbm2((vSkinPos + vec3(0.0, 0.0, PORE_E)) * PORE_SCALE));
      float skinMid = fbm3(vSkinPos * 22.0);
      float skinBig = fbm3(vSkinPos * 4.1);
      diffuseColor.rgb *= 1.0 + (skinMid - 0.5) * uColorVar + (skinBig - 0.5) * uColorVar * 1.2;
      diffuseColor.rgb = mix(diffuseColor.rgb, diffuseColor.rgb * vec3(1.07, 0.93, 0.89),
                            0.45 * skinMid + 0.20 * skinPore);
    `)
    .replace('#include <roughnessmap_fragment>', `#include <roughnessmap_fragment>
      roughnessFactor = clamp(roughnessFactor + (skinPore - 0.5) * uPoreR + (skinMid - 0.5) * uMidR, 0.12, 1.0);
    `)
    .replace('#include <normal_fragment_maps>', `#include <normal_fragment_maps>
      {
        vec3 g = (poreOff - skinPore) * (uBump / PORE_E);
        g -= normal * dot(g, normal);
        normal = normalize(normal - g);
      }
    `)
    .replace('#include <lights_fragment_end>', `#include <lights_fragment_end>
      {
        vec3 L = normalize(uSSSDir);
        float back = clamp(dot(normal, -L) * 0.5 + 0.5, 0.0, 1.0);
        float w = pow(back, 3.0) * (0.55 + 0.45 * skinMid);
        reflectedLight.indirectDiffuse += uSSSColor * w * uSSS * diffuseColor.rgb * 2.0;
      }
    `);
};

