function resize() {
  const w = stage.clientWidth || 400;
  const h = stage.clientHeight || 400;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(w, h, false);
  camera.aspect = w / h;
  camera.updateProjectionMatrix();
  refit(w, h);
}

function refit(w, h) {
  const vHalf = (FOV * 0.5) * Math.PI / 180;
  const hHalf = Math.atan(Math.tan(vHalf) * (w / h));
  const d = RADIUS / Math.sin(Math.min(vHalf, hHalf));
  const t = controls.target;
  const cur = camera.position.distanceTo(t);
  if (cur > 1e-6) {
    camera.position.sub(t).multiplyScalar(d / cur).add(t);
  } else {
    camera.position.set(t.x, t.y, t.z + d);
  }
  camera.updateProjectionMatrix();
}
new ResizeObserver(resize).observe(stage);
resize();

